				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		if ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "inscripcion_id IN (SELECT i.id FROM inscripciones i INNER JOIN cursos c ON c.id = i.curso_id WHERE c.profesor_id = " . intval($_SESSION["profesor_id"]) . ")");
} elseif ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "inscripcion_id IN (SELECT id FROM inscripciones WHERE estudiante_id = " . intval($_SESSION["estudiante_id"]) . ")");
}

// Pestañas de filtro
if (isset($_GET["f_tab"])) {
    $_SESSION["notas_tab"] = $_GET["f_tab"];
}
$tab = isset($_SESSION["notas_tab"]) ? $_SESSION["notas_tab"] : "todos";

if ($tab == "aprobados") {
    $strWhereClause = whereAdd($strWhereClause, "nota >= 2");
} elseif ($tab == "inhabilitados") {
    $strWhereClause = whereAdd($strWhereClause, "(COALESCE(Puntos_Primer_Parcial,0) + COALESCE(Puntos_Segundo_Parcial,0) + COALESCE(Puntos_Trabajo_Practico,0) + COALESCE(Puntos_Asistencia,0)) < 30");
} elseif ($tab == "reprobados") {
    $strWhereClause = whereAdd($strWhereClause, "nota = 1 AND (COALESCE(Puntos_Primer_Parcial,0) + COALESCE(Puntos_Segundo_Parcial,0) + COALESCE(Puntos_Trabajo_Practico,0) + COALESCE(Puntos_Asistencia,0)) >= 30");
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$insc_id = intval($values["inscripcion_id"]);
$p1      = intval($values["Puntos_Primer_Parcial"]);
$p2      = intval($values["Puntos_Segundo_Parcial"]);
$tp      = intval($values["Puntos_Trabajo_Practico"]);
$asist   = intval($values["Puntos_Asistencia"]);
$final   = intval($values["Puntos_Examen_Final"]);
$extra   = intval($values["Puntos_Examen_Extra_Ord"]);
$mesa    = intval($values["Puntos_Examen_Extra_Extra_Ord"]);

// 1. Validar topes máximos por reglamento
if ($p1 < 0 || $p1 > 15) {
    $message = "El 1° Parcial debe estar entre 0 y 15 puntos.";
    return false;
}
if ($p2 < 0 || $p2 > 15) {
    $message = "El 2° Parcial debe estar entre 0 y 15 puntos.";
    return false;
}
if ($tp < 0 || $tp > 15) {
    $message = "Trabajos Prácticos debe estar entre 0 y 15 puntos.";
    return false;
}
if ($asist < 0 || $asist > 5) {
    $message = "Puntos de asistencia debe estar entre 0 y 5 puntos.";
    return false;
}
if ($final < 0 || $final > 50 || $extra < 0 || $extra > 50 || $mesa < 0 || $mesa > 50) {
    $message = "El examen final / extraordinario no puede superar los 50 puntos.";
    return false;
}

// 2. Control de Bloqueo Financiero para rendir Examen Final
$rsDeuda = DB::Query("SELECT COUNT(*) AS total FROM pagos p 
                      INNER JOIN inscripciones i ON i.estudiante_id = p.estudiante_id 
                      WHERE i.id = " . $insc_id . " AND (p.estado = 'Vencido' OR (p.estado = 'Pendiente' AND p.fecha_vencimiento < CURDATE()))");
$rD = $rsDeuda->fetchAssoc();
if (intval($rD["total"]) > 0 && ($final > 0 || $extra > 0 || $mesa > 0)) {
    $message = "Bloqueo Financiero: El estudiante registra cuotas vencidas en Tesorería. No está habilitado para rendir evaluaciones finales.";
    return false;
}

// 3. Regla Oficial Res. 24/18 (Proceso mínimo 30 pts)
$proceso = $p1 + $p2 + $tp + $asist;
$mejor_examen = max($final, $extra, $mesa);

if ($mesa > 0) {
    $values["tipo_evaluacion"] = "Mesa Especial";
} elseif ($extra > 0) {
    $values["tipo_evaluacion"] = "Extraordinario";
} else {
    $values["tipo_evaluacion"] = "Final Ordinario";
}

if ($proceso < 30) {
    $values["nota"] = 1;
    $values["descripcion"] = "Inhabilitado por Proceso";
} else {
    $total = $proceso + $mejor_examen;
    if ($total >= 91) {
        $values["nota"] = 5; $values["descripcion"] = "Aprobado";
    } elseif ($total >= 81) {
        $values["nota"] = 4; $values["descripcion"] = "Aprobado";
    } elseif ($total >= 71) {
        $values["nota"] = 3; $values["descripcion"] = "Aprobado";
    } elseif ($total >= 60) {
        $values["nota"] = 2; $values["descripcion"] = "Aprobado";
    } else {
        $values["nota"] = 1;
        $values["descripcion"] = ($mejor_examen > 0) ? "Reprobado" : "Pendiente";
    }
}

$values["fecha_registro"] = date("Y-m-d H:i:s");
return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
