				// Before display
function BeforeShowList(&$xt, &$templatefile, &$pageObject)
{

		$tab_actual = isset($_SESSION["notas_tab"]) ? $_SESSION["notas_tab"] : "todos";

$sqlCounts = "SELECT 
    COUNT(*) AS total,
    SUM(CASE WHEN nota >= 2 THEN 1 ELSE 0 END) AS aprobados,
    SUM(CASE WHEN (Puntos_Primer_Parcial + Puntos_Segundo_Parcial + Puntos_Trabajo_Practico + Puntos_Asistencia) < 30 THEN 1 ELSE 0 END) AS inhabilitados,
    SUM(CASE WHEN nota = 1 AND (Puntos_Primer_Parcial + Puntos_Segundo_Parcial + Puntos_Trabajo_Practico + Puntos_Asistencia) >= 30 THEN 1 ELSE 0 END) AS reprobados
    FROM notas";

$rsCounts = DB::Query($sqlCounts);
$counts = $rsCounts->fetchAssoc();

$pageObject->setProxyValue("tab_counts", $counts);
$pageObject->setProxyValue("active_tab", $tab_actual);

// Pasar el rol activo al navegador
$rol_actual = isset($_SESSION["rol"]) ? $_SESSION["rol"] : "Invitado";
$pageObject->setProxyValue("user_rol", $rol_actual);

// Ocultar también a nivel de render si no es Admin ni Docente
if ($rol_actual != "Admin" && $rol_actual != "Docente") {
    $pageObject->hideItem("custom_button");
}
;		
} // function BeforeShowList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: After record processed
function BeforeMoveNextList(&$data, &$row, &$record, $recordId, &$pageObject)
{

		// Badges de condición académica
if ($data["descripcion"] == "Aprobado") {
    $row["descripcion_value"] = '<span class="label label-success" style="font-size:11px; padding:3px 7px;"><i class="fa fa-graduation-cap"></i> Aprobado</span>';
} elseif (strpos($data["descripcion"], "Inhabilitado") !== false) {
    $row["descripcion_value"] = '<span class="label label-danger" style="font-size:11px; padding:3px 7px;"><i class="fa fa-ban"></i> Inhabilitado</span>';
} elseif ($data["descripcion"] == "Reprobado") {
    $row["descripcion_value"] = '<span class="label label-danger" style="font-size:11px; padding:3px 7px;"><i class="fa fa-times"></i> Reprobado</span>';
} else {
    $row["descripcion_value"] = '<span class="label label-warning" style="font-size:11px; padding:3px 7px; color:#000;">Pendiente</span>';
}
;		
} // function BeforeMoveNextList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



